function extractYoutubeId(value:string){try{const u=new URL(value);if(u.hostname.includes('youtu.be'))return u.pathname.slice(1).split('/')[0];if(u.searchParams.get('v'))return u.searchParams.get('v');const m=u.pathname.match(/\/(?:embed|shorts|live)\/([^/?]+)/);return m?.[1]||''}catch{return''}}
function extractInstagramEmbed(value:string){try{const u=new URL(value);if(!/instagram\.com$/i.test(u.hostname)&&!/\.instagram\.com$/i.test(u.hostname))return'';const m=u.pathname.match(/\/reel\/([^/?#]+)/);if(!m)return'';return`https://www.instagram.com/reel/${m[1]}/embed/?hidecaption=1`;}catch{return''}}
function normalizeVideo(v:any){const platform=v.platform||(/instagram\.com/i.test(v.embed_url||'')?'instagram':/youtu/i.test(v.embed_url||'')?'youtube':'vimeo');let embed=v.embed_url||v.source_url||'';if(platform==='youtube'){const id=v.video_id||extractYoutubeId(embed);embed=id?`https://www.youtube.com/embed/${id}?enablejsapi=1&playsinline=1&rel=0&modestbranding=1`:embed;return{...v,platform,video_id:id,embed_url:embed}}if(platform==='instagram'){embed=extractInstagramEmbed(v.source_url||embed)||embed;return{...v,platform,embed_url:embed}}return{...v,platform,embed_url:embed}}
