function Archive({photos,videos,compact=false}:{photos:any[],videos:any[],compact?:boolean}){const live=photos.length?photos.map(p=>({...p,image:p.image_url||'/catalogue-reference.webp',category:p.category||p.occasion||'Other'})):DemoArchive(),initialCategory=new URLSearchParams(location.search).get('category')||'All',[cat,setCat]=useState(initialCategory),[open,setOpen]=useState<any>(null);const cats=Array.from(new Set(live.map(p=>p.category))).sort();const shown=live.filter(p=>cat==='All'||p.category===cat);const categoryVideos=videos.map(normalizeVideo).filter(v=>cat==='All'||!v.category||v.category===cat);return <section className={`archive section ${compact?'compactArchive':''}`}><div className="wrap"><div className="archiveHead"><div><small>{compact?'SELECTED WORK':'THE GALLERY'}</small><h2>{compact?'A glimpse of the stories.':'Our gallery.'}</h2><p className="muted">{compact?'A small selection of moments. Explore the complete gallery by category.':'A collection of photographs and films, organized by story rather than by year.'}</p></div>{compact&&<a className="btn darkBtn" href="/gallery">Explore the Gallery <ArrowRight size={17}/></a>}</div>{!compact&&<div className="categories galleryCategories">{['All',...cats.filter(x=>x!=='All')].map(c=><button key={c} className={cat===c?'active':''} onClick={()=>setCat(c)}>{c}</button>)}</div>}<div className="archiveGrid">{shown.slice(0,compact?8:999).map((p,i)=><button className="archiveItem" key={p.id} onClick={()=>setOpen({i})}><img src={p.image} alt={p.caption||`${p.category} photography`} loading="lazy"/><span>{p.category}</span></button>)}</div>{!shown.length&&<div className="empty">No photographs in this category yet.</div>}{!compact&&categoryVideos.length>0&&<div className="projectFilms"><div><small>FILMS</small><h3>Stories in motion.</h3></div><VideoDeck videos={categoryVideos}/></div>}</div>{open&&<Lightbox items={shown} index={open.i} close={()=>setOpen(null)}/>}</section>}
