function extractCategoryFromHashtags(caption:string){const tags=(caption.match(/#[\p{L}0-9_-]+/gu)||[]).map(t=>t.slice(1).toLowerCase().replace(/[_\s-]/g,''));const map:[string,string[]][]=[['Beach',['beach']],['Birthday',['birthday']],['Family',['family']],['Maternity',['maternity']],['Portfolio',['portfolio']],['Pre-Wedding',['prewedding']],['Wedding',['wedding']]];for(const [cat,aliases]of map)if(tags.some(t=>aliases.includes(t)))return cat;return'Other'}
function toWebp(file:File){return new Promise<File>((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const max=2400,s=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*s)),h=Math.max(1,Math.round(img.height*s));const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');if(!x)return reject(new Error('Could not process image'));x.drawImage(img,0,0,w,h);c.toBlob(blob=>{URL.revokeObjectURL(url);if(!blob)return reject(new Error('This browser could not create WebP'));resolve(new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp',lastModified:Date.now()}))},'image/webp',.86)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Could not read image'))};img.src=url})}
function scoreImage(file:File){return new Promise<any>((resolve,reject)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{const max=640,s=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*s)),h=Math.max(1,Math.round(img.height*s));const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true})!;x.drawImage(img,0,0,w,h);const d=x.getImageData(0,0,w,h).data,gray=new Float32Array(w*h);let sum=0,sum2=0,bright=0,clip=0,edges=0;for(let y=0;y<h;y++)for(let xx=0;xx<w;xx++){const i=(y*w+xx)*4,g=.299*d[i]+.587*d[i+1]+.114*d[i+2];gray[y*w+xx]=g;sum+=g;sum2+=g*g;bright+=Math.abs(g-128);if(g<8||g>247)clip++}for(let y=1;y<h-1;y++)for(let xx=1;xx<w-1;xx++){const i=y*w+xx,lap=gray[i-1]+gray[i+1]+gray[i-w]+gray[i+w]-4*gray[i];edges+=lap*lap}const mean=sum/(w*h),variance=sum2/(w*h)-mean*mean,sharp=Math.min(100,Math.max(0,edges/(w*h)*1.7)),exposure=Math.max(0,100-Math.abs(mean-128)*.75-clip/(w*h)*100),contrast=Math.min(100,Math.sqrt(Math.max(0,variance))*1.15),brightness=Math.max(0,100-Math.abs(mean-128)*.7),clarity=Math.min(100,sharp*.65+contrast*.35),color=Math.min(100,80+Math.min(20,bright/(w*h)*.5)),composition=Math.min(100,60+Math.min(40,Math.abs(w/h-1.5)*15)),total=sharp*.25+brightness*.15+exposure*.15+contrast*.1+clarity*.15+color*.1+composition*.1,phash=Array.from({length:8},(_,yy)=>Array.from({length:8},(_,xx)=>gray[Math.min(h-1,Math.floor((yy+.5)*h/8))*w+Math.min(w-1,Math.floor((xx+.5)*w/8))]>mean?'1':'0').join('')).join('');URL.revokeObjectURL(url);resolve({width:img.width,height:img.height,bytes:file.size,sharpness:sharp,brightness,exposure,contrast,clarity,color,composition,similarity:0,total_score:total,phash})};img.onerror=reject;img.src=url})}
function hamming(a:string,b:string){let n=0;for(let i=0;i<Math.min(a.length,b.length);i++)if(a[i]!==b[i])n++;return n+Math.abs(a.length-b.length)}
